def _process(proc_data: List[Dict]) -> List[Dict]:
    """
    Final processing to conform to the schema.

    Parameters:

        proc_data:   (List of Dictionaries) raw structured data to process

    Returns:

        List of Dictionaries. Structured to conform to the schema.
    """
    int_list = {
        'process', 'sent', 'received', 'total_size', 'matches', 'hash_hits',
        'false_alarms', 'data', 'total_files', 'regular_files', 'dir_files',
        'total_created_files', 'created_regular_files', 'created_dir_files',
        'deleted_files', 'transferred_files', 'transferred_file_size',
        'literal_data', 'matched_data', 'file_list_size'
    }

    float_list = {
        'bytes_sec', 'speedup', 'file_list_generation_time',
        'file_list_transfer_time'
    }

    for item in proc_data:
        for key in item['summary']:
            if key in int_list:
                item['summary'][key] = jc.utils.convert_size_to_int(item['summary'][key])

            if key in float_list:
                converted_val: Union[float, None] = None
                val = item['summary'][key]
                if any([
                    'K' in val,
                    'M' in val,
                    'G' in val,
                    'T' in val
                ]):
                    converted_int_val = jc.utils.convert_size_to_int(val)

                    if not converted_int_val is None:
                        converted_val = float(converted_int_val)

                else:
                    converted_val = jc.utils.convert_to_float(val)

                item['summary'][key] = converted_val

        for entry in item['files']:
            for key in entry:
                if key in int_list:
                    entry[key] = jc.utils.convert_to_int(entry[key])

            # add timestamp
            if 'date' in entry and 'time' in entry:
                date = entry['date'].replace('/', '-')
                date_time = f'{date} {entry["time"]}'
                ts = jc.utils.timestamp(date_time, format_hint=(7250,))
                entry['epoch'] = ts.naive

    return proc_data

